arguments.document:
query VerifyDecliningRangeMerchandising {
  products(first: 50, query: "status:active") {
    nodes {
      id
      title
      handle
      status
      totalInventory
      variants(first: 20) {
        nodes {
          id
          inventoryQuantity
        }
      }
    }
  }
  collections(first: 50) {
    nodes {
      id
      title
      handle
      productsCount {
        count
      }
    }
  }
}

